def sec(**k): S.append(k)
def we(given, find, strat, steps, ans, sanity, sig, py): return dict(given=given, find=find, strat=strat, steps=steps, ans=ans, sanity=sanity, sig=sig, py=py)
def npq(q, val, unit, hints, sol, tol=0.005, extra=None):
    d = dict(q=q, val=val, unit=unit, hints=hints, sol=sol, tol=tol)
    if extra: d['extra'] = extra
    return d
